class Solution:
    def swapNodes(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        first = head
        for _ in range(k - 1):
            first = first.next
        second = head
        curr = first
        while curr.next:
            curr = curr.next
            second = second.next
        first.val, second.val = second.val, first.val
        return head

class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
        ListNode* first = head;
        for (int i = 0; i < k - 1; i++) first = first->next;
        ListNode* second = head;
        ListNode* curr = first;
        while (curr->next) {
            curr = curr->next;
            second = second->next;
        }
        int tmp = first->val;
        first->val = second->val;
        second->val = tmp;
        return head;
    }
};

class Solution {
    public ListNode swapNodes(ListNode head, int k) {
        ListNode first = head;
        for (int i = 0; i < k - 1; i++) first = first.next;
        ListNode second = head;
        ListNode curr = first;
        while (curr.next != null) {
            curr = curr.next;
            second = second.next;
        }
        int tmp = first.val;
        first.val = second.val;
        second.val = tmp;
        return head;
    }
}

var swapNodes = function(head, k) {
    let first = head;
    for (let i = 0; i < k - 1; i++) first = first.next;
    let second = head;
    let curr = first;
    while (curr.next !== null) {
        curr = curr.next;
        second = second.next;
    }
    const tmp = first.val;
    first.val = second.val;
    second.val = tmp;
    return head;
};
